// TP : radar de recul. Plus l’obstacle est proche, plus le buzzer bipe vite.
const int TRIG = 7;
const int ECHO = 8;
const int BUZZER = 2;

// Distance en cm : impulsion de 10 µs sur TRIG, puis durée de l’écho.
float mesurerDistance() {
  digitalWrite(TRIG, LOW);
  delayMicroseconds(2);
  digitalWrite(TRIG, HIGH);
  delayMicroseconds(10);
  digitalWrite(TRIG, LOW);
  long duree = pulseIn(ECHO, HIGH, 30000); // 0 si aucun écho en 30 ms
  return duree / 58.0;
}

void setup() {
  Serial.begin(9600);
  pinMode(TRIG, OUTPUT);
  pinMode(ECHO, INPUT);
  pinMode(BUZZER, OUTPUT);
}

void loop() {
  float cm = mesurerDistance();
  Serial.print("Distance : ");
  Serial.print(cm);
  Serial.println(" cm");

  if (cm > 0 && cm < 10) {
    digitalWrite(BUZZER, HIGH); // très près : son continu
    delay(100);
  } else if (cm > 0 && cm < 100) {
    digitalWrite(BUZZER, HIGH); // un bip court...
    delay(50);
    digitalWrite(BUZZER, LOW);
    delay(cm * 4);              // ...puis une pause, plus courte quand l’obstacle approche
  } else {
    digitalWrite(BUZZER, LOW);  // rien à moins d’un mètre : silence
    delay(200);
  }
}

text.fr:
Dans l’onglet « Code », écrivez une fonction qui mesure la distance :
- `digitalWrite(7, HIGH); delayMicroseconds(10); digitalWrite(7, LOW);` : l’impulsion de déclenchement ;
- `long duree = pulseIn(8, HIGH, 30000);` : la durée de l’écho en µs (0 si rien ne revient en 30 ms) ;
- `float cm = duree / 58.0;`
Dans loop() : sous **10 cm**, buzzer allumé en continu ; sous **100 cm**, un bip de 50 ms suivi d’une pause de `cm * 4` ms ; au-delà, silence. Cliquez sur « Téléverser ».

text.en:
In the “Code” tab, write a function that measures the distance:
- `digitalWrite(7, HIGH); delayMicroseconds(10); digitalWrite(7, LOW);`: the trigger pulse;
- `long duree = pulseIn(8, HIGH, 30000);`: the echo time in µs (0 if nothing comes back within 30 ms);
- `float cm = duree / 58.0;`
In loop(): below **10 cm**, buzzer on continuously; below **100 cm**, a 50 ms beep followed by a `cm * 4` ms pause; beyond that, silence. Click “Upload”.
